73	
74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
81	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
82	     */
83	    private static final Pattern EMAIL_PATTERN =
84	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
85	
86	    /**
87	     * Email domains rejected as disposable/throwaway addresses. An owner whose email domain matches
88	     * one of these (compared case-insensitively) is rejected with 400.
89	     */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
91	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    /**
94	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
95	     * new owner's id, customerCode, registrationDate, membershipLevel and membershipNumber.
96	     */
97	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
98	
99	    /**
100	     * Common street-type abbreviations expanded during address normalization, keyed by the
101	     * upper-cased abbreviation.
102	     */
103	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
104	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
105	
106	    /**
107	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
108	     * city already holds this many owners.
109	     */
110	    private static final int CITY_CAPACITY = 50;
111	
112	    /**
113	     * Maximum number of owners that may be created on a single day. A create is rejected once this
114	     * many owners already carry the current day as their {@code registrationDate}.
115	     */
116	    private static final int DAILY_OWNER_LIMIT = 100;
117	
118	    /**
119	     * Fixed public holidays that the business-day roll skips: when an adjusted registration date lands
120	     * on one of these it advances to the next non-holiday business day.
121	     */
122	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
123	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
124	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
125	
126	    private final ClinicService clinicService;
127	
128	    private final OwnerMapper ownerMapper;
129	
130	    private final PetMapper petMapper;
131	
132	    private final VisitMapper visitMapper;
133	
134	    public OwnerRestControllerV1(ClinicService clinicService,
135	                                 OwnerMapper ownerMapper,
136	                                 PetMapper petMapper,
137	                                 VisitMapper visitMapper) {
138	        this.clinicService = clinicService;
139	        this.ownerMapper = ownerMapper;
140	        this.petMapper = petMapper;
141	        this.visitMapper = visitMapper;
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
147	        Collection<Owner> owners;
148	        if (lastName != null) {
149	            owners = this.clinicService.findOwnerByLastName(lastName);
150	        } else {
151	            owners = this.clinicService.findAllOwners();
152	        }
153	        if (owners.isEmpty()) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
172	        validateRequiredFields(ownerFieldsDto);
173	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
174	        HttpHeaders headers = new HttpHeaders();
175	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
176	        applyAddress(owner, ownerFieldsDto);
177	        rejectFutureRegistrationDate(owner.getRegistrationDate());
178	        LocalDate effectiveDate = owner.getRegistrationDate() == null
179	            ? LocalDate.now()
180	            : owner.getRegistrationDate();
181	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
182	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
183	        rejectWhenCityAtCapacity(owner.getCity());
184	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
185	        applyHousehold(owner, sharesHousehold);
186	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
187	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
188	        rejectDuplicateIdentity(owner);
189	        owner.setCustomerCode(customerCode(owner));
190	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
191	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
192	        flagPossibleDuplicate(owner, sharesHousehold);
193	        this.clinicService.saveOwner(owner);
194	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
195	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
196	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
197	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    /**
204	     * Builds the owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the region
205	     * code derived from the owner's postcode (falling back to the city-to-region table, then
206	     * {@code UNKNOWN}) and HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the
207	     * owner's normalized telephone concatenated with its last name (e.g. {@code NSW-1A2B3C4D}).
208	     *
209	     * <p>Should the computed code collide with an existing owner's {@code customerCode}, it is
210	     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
211	     * unique (e.g. {@code NSW-1A2B3C4D-2}), so distinct owners always receive distinct customer codes.
212	     *
213	     * @param owner the owner being created, with its normalized telephone already applied
214	     * @return the assigned, de-duplicated customer code
215	     */
216	    private String customerCode(Owner owner) {
217	        String base = regionCode(owner) + "-" + identityHash8(owner.getTelephone(), owner.getLastName());
218	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
219	            .map(Owner::getCustomerCode)
220	            .filter(code -> code != null)
221	            .collect(java.util.stream.Collectors.toSet());
222	        if (!existingCodes.contains(base)) {
223	            return base;
224	        }
225	        int n = 2;
226	        while (existingCodes.contains(base + "-" + n)) {
227	            n++;
228	        }
229	        return base + "-" + n;
230	    }
231	
232	    /**
233	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
234	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
235	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
236	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
237	     * postcode nor the city identifies a region.
238	     *
239	     * @param owner the owner being created
240	     * @return the derived region code, never {@code null}
241	     */
242	    private String regionCode(Owner owner) {
243	        String fromPostcode = regionFromPostcode(owner.getPostcode());
244	        if (fromPostcode != null) {
245	            return fromPostcode;
246	        }
247	        String fromCity = region(owner.getCity());
248	        return fromCity == null ? "UNKNOWN" : fromCity;
249	    }
250	
251	    /**
252	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
253	     * postcode is absent, not 4 digits, or in no known range.
254	     *
255	     * @param postcode the owner's postcode, may be {@code null}
256	     * @return the region code, or {@code null} when no known range contains the postcode
257	     */
258	    private String regionFromPostcode(String postcode) {
259	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
260	            return null;
261	        }
262	        int value = Integer.parseInt(postcode);
263	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
264	            int[] range = entry.getValue();
265	            if (value >= range[0] && value <= range[1]) {
266	                return entry.getKey();
267	            }
268	        }
269	        return null;
270	    }
271	
272	    /**
273	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
274	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
275	     *
276	     * @param telephone the owner's normalized (E.164) telephone
277	     * @param lastName  the owner's last name
278	     * @return the 8-character upper-cased hex hash
279	     */
280	    private String identityHash8(String telephone, String lastName) {
281	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
282	        try {
283	            byte[] digest = MessageDigest.getInstance("SHA-256")
284	                .digest(input.getBytes(StandardCharsets.UTF_8));
285	            StringBuilder hex = new StringBuilder(digest.length * 2);
286	            for (byte b : digest) {
287	                hex.append(String.format("%02x", b));
288	            }
289	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
290	        } catch (NoSuchAlgorithmException ex) {
291	            throw new IllegalStateException("SHA-256 not available", ex);
292	        }
293	    }
294	
295	    /**
296	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
297	     * last two digits of the fiscal year of the owner's business-day-adjusted registration date,
298	     * zero-padded (e.g. {@code NSW-1A2B3C4D-M26}). The fiscal year starts on 1 July.
299	     *
300	     * @param customerCode     the owner's assigned customer code
301	     * @param registrationDate the owner's business-day-adjusted registration date
302	     * @return the assigned membership number
303	     */
304	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
305	        return String.format("%s-M%02d", customerCode, fiscalYear(registrationDate) % 100);
306	    }
307	
308	    /**
309	     * The month the fiscal year starts on (1 July).
310	     */
311	    private static final int FISCAL_YEAR_START_MONTH = 7;
312	
313	    /**
314	     * Derives the fiscal year of the given date. The fiscal year starts on 1 July, so a date on or
315	     * after 1 July belongs to the following calendar year's fiscal year (e.g. 2026-07-01 is fiscal
316	     * year 2027) while an earlier date takes the calendar year unchanged.
317	     *
318	     * @param date the date to derive the fiscal year of
319	     * @return the fiscal year
320	     */
321	    private int fiscalYear(LocalDate date) {
322	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
323	    }
324	
325	    /**
326	     * Counts the existing owners that already share the given firstName and lastName, compared
327	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
328	     * the owners that pre-existed this create.
329	     *
330	     * @param firstName the new owner's first name
331	     * @param lastName  the new owner's last name
332	     * @return the number of existing namesakes
333	     */
334	    private int countNamesakes(String firstName, String lastName) {
335	        return (int) this.clinicService.findAllOwners().stream()
336	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
337	                && equalsIgnoreCase(existing.getLastName(), lastName))
338	            .count();
339	    }
340	
341	    /**
342	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
343	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
344	     * still resemble an existing owner: when it shares an existing owner's lastName (compared
345	     * case-insensitively) and postcode while carrying a different telephone, the owner is flagged
346	     * with {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing
347	     * owner's id. When no such owner exists the flag is set to {@code false} and no match id is
348	     * recorded. An owner with no postcode can never soft-match and is always {@code false}.
349	     *
350	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
351	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
352	     * always flagged {@code false}.
353	     *
354	     * @param owner           the owner being created, with its normalized telephone already applied
355	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
356	     *                        never flagged as a possible duplicate
357	     */
358	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
359	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
360	        if (match != null) {
361	            owner.setPossibleDuplicate(true);
362	            owner.setPossibleDuplicateOf(match.getId());
363	        } else {
364	            owner.setPossibleDuplicate(false);
365	            owner.setPossibleDuplicateOf(null);
366	        }
367	    }
368	
369	    /**
370	     * Finds the existing owner this owner soft-matches: same lastName (case-insensitive) and same
371	     * postcode, but a different telephone. When several existing owners match, the one with the
372	     * lowest id is chosen so the result is deterministic. Returns {@code null} when the owner has no
373	     * postcode or no such existing owner exists.
374	     *
375	     * @param owner the owner being created
376	     * @return the matching existing owner, or {@code null} when there is no soft-match
377	     */
378	    private Owner findPossibleDuplicate(Owner owner) {
