383	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
384	                && owner.getPostcode().equals(existing.getPostcode())
385	                && !equalsIgnoreCase(existing.getTelephone(), owner.getTelephone()))
