440	    /**
441	     * Rolls a registration date forward onto a business day: while it falls on a Saturday, a Sunday or
442	     * a listed {@link #PUBLIC_HOLIDAYS public holiday} it advances one day at a time until it lands on
443	     * a non-holiday weekday, otherwise it is returned unchanged. Applied to the effective registration
444	     * date (whether supplied in the request or defaulted to the server date) so a weekend or holiday
445	     * value never persists as an owner's {@code registrationDate}.
446	     *
447	     * @param date the effective registration date
448	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
449	     */
450	    private LocalDate toBusinessDay(LocalDate date) {
451	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
452	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
453	            || PUBLIC_HOLIDAYS.contains(date)) {
454	            date = date.plusDays(1);
455	        }
456	        return date;
457	    }
