515	    /**
516	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
517	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
518	     */
519	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
520	        "NSW", new int[] {2000, 2099},
521	        "VIC", new int[] {3000, 3099},
522	        "QLD", new int[] {4000, 4099});
