524	    /**
525	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
526	     * is optional and accepted, keeping the create contract backward-compatible. When present the
527	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
528	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
529	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
530	     *
531	     * @param postcode the raw postcode value as submitted, may be {@code null}
532	     * @param city     the owner's city, used to resolve the region whose range applies
533	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
534	     *                                  the city's region
535	     */
536	    private void validatePostcode(String postcode, String city) {
537	        if (isBlank(postcode)) {
538	            return;
539	        }
540	        if (!postcode.matches("[0-9]{4}")) {
541	            throw new InvalidPostcodeException(postcode, city);
542	        }
543	        String region = region(city);
544	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
545	        if (range != null) {
546	            int value = Integer.parseInt(postcode);
547	            if (value < range[0] || value > range[1]) {
548	                throw new InvalidPostcodeException(postcode, city);
549	            }
550	        }
551	    }
