553	    /**
554	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
555	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
556	     *
557	     * @param city the owner's city
558	     * @return the region code, or {@code null} when the city has no known region
559	     */
560	    private String region(String city) {
561	        if (city == null) {
562	            return null;
563	        }
564	        return switch (city) {
565	            case "Sydney" -> "NSW";
566	            case "Melbourne" -> "VIC";
567	            case "Brisbane" -> "QLD";
568	            default -> null;
569	        };
570	    }
