572	    /**
573	     * The number of national (subscriber) digits an E.164 number must carry for a given country
574	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
575	     * national digits and the North American Numbering Plan ('+1') requires 10.
576	     */
577	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
578	        Map.of("61", 9, "1", 10);
579	
580	    /**
581	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
582	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
583	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
584	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
585	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
586	     *
587	     * @param telephone the raw telephone value as submitted
588	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
589	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
590	     *                                   national-number length is wrong for its country code
591	     */
592	    private String normalizeTelephone(String telephone) {
593	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
594	        String nationalSignificantNumber;
595	        if (cleaned.startsWith("+")) {
596	            nationalSignificantNumber = cleaned.substring(1);
597	        } else {
598	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
599	            nationalSignificantNumber = "61" + national;
600	        }
601	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
602	            throw new InvalidTelephoneException(telephone);
603	        }
604	        validateNationalNumberLength(nationalSignificantNumber, telephone);
605	        return "+" + nationalSignificantNumber;
606	    }
607	
608	    /**
609	     * Validates the national-number length of an E.164 number against its country calling code. The
610	     * significant number is a country code immediately followed by the national digits; for each
611	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
612	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
613	     * left unchecked.
614	     *
615	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
616	     * @param rejectedValue             the raw telephone value, reported on rejection
617	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
618	     */
619	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
620	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
621	            String countryCode = rule.getKey();
622	            if (nationalSignificantNumber.startsWith(countryCode)) {
623	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
624	                if (nationalDigits != rule.getValue()) {
625	                    throw new InvalidTelephoneException(rejectedValue);
626	                }
627	                return;
628	            }
629	        }
630	    }
