632	    /**
633	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
634	     * value is treated as absent and returns {@code null}); when present the value must be a
635	     * syntactically valid address, and is stored and returned lower-cased.
636	     *
637	     * @param email the raw email value as submitted, may be {@code null}
638	     * @return the lower-cased email, or {@code null} when none was supplied
639	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
640	     */
641	    private String normalizeEmail(String email) {
642	        if (email == null || email.isBlank()) {
643	            return null;
644	        }
645	        String normalized = email.trim().toLowerCase();
646	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
647	            throw new InvalidEmailException(email);
648	        }
649	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
650	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
651	            throw new DisposableEmailException(email);
652	        }
653	        return normalized;
654	    }
