656	    /**
657	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
658	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
659	     * key is the normalized telephone, email and householdId joined together, this one check
660	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
661	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
662	     * with different telephones have different keys and are both allowed.
663	     *
664	     * @param owner the owner being created, with its normalized telephone, email and householdId
665	     *              already applied
666	     * @throws DuplicateIdentityException if another owner already has the same identityKey
667	     */
668	    private void rejectDuplicateIdentity(Owner owner) {
669	        String identityKey = identityKey(owner);
670	        boolean inUse = this.clinicService.findAllOwners().stream()
671	            .filter(existing -> !isDeleted(existing))
672	            .map(this::identityKey)
673	            .anyMatch(identityKey::equals);
674	        if (inUse) {
675	            throw new DuplicateIdentityException(identityKey);
676	        }
677	    }
