679	    /**
680	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
681	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
682	     * duplicate decision is made by comparing whole identityKeys.
683	     *
684	     * @param owner the owner whose identityKey to derive
685	     * @return the derived identityKey
686	     */
687	    private String identityKey(Owner owner) {
688	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
689	        String email = owner.getEmail() == null ? "" : owner.getEmail();
690	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
691	        return telephone + "|" + email + "|" + householdId;
692	    }
