694	    /**
695	     * Applies the household rule to an owner being created. The household is keyed on
696	     * (lastName, postcode): the owner is assigned the deterministic {@link #householdId(Owner)
697	     * householdId} derived from its normalized lastName and postcode, so owners sharing a lastName
698	     * and postcode automatically share the identifier — the link is computed, not created by a flag.
699	     *
700	     * <p>Because the household is keyed on (lastName, postcode), any existing owner that derives the
701	     * same householdId is a member of the same household, and a second owner joining it is a
702	     * household duplicate. Such a create is rejected with 409 unless the request declares
703	     * {@code sharesHousehold=true}, in which case it is allowed through as a declared household
704	     * member. The {@code sharesHousehold} directive only bypasses this duplicate block.
705	     *
706	     * @param owner           the owner being created
707	     * @param sharesHousehold whether the request declared it shares a household, bypassing the block
708	     * @throws HouseholdDuplicateException if an existing owner already shares the household and the
709	     *                                     request did not declare {@code sharesHousehold=true}
710	     */
711	    private void applyHousehold(Owner owner, boolean sharesHousehold) {
712	        String householdId = householdId(owner);
713	        owner.setHouseholdId(householdId);
714	        boolean householdExists = this.clinicService.findAllOwners().stream()
715	            .filter(existing -> !isDeleted(existing))
716	            .anyMatch(existing -> householdId.equals(householdId(existing)));
717	        if (householdExists && !sharesHousehold) {
718	            throw new HouseholdDuplicateException(householdId);
719	        }
720	    }
721	
722	    /**
723	     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
724	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the owner's normalized
725	     * lastName, a {@code '|'} separator, and its postcode. Being a pure function of (lastName,
726	     * postcode), every owner sharing a lastName and postcode derives the same value regardless of
727	     * creation order. A {@code null} postcode contributes an empty segment.
728	     *
729	     * @param owner the owner whose household identifier to derive
730	     * @return the household identifier
731	     */
732	    private String householdId(Owner owner) {
733	        String lastNameKey = toHouseholdKey(owner.getLastName());
734	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
735	        try {
736	            byte[] digest = MessageDigest.getInstance("SHA-256")
737	                .digest((lastNameKey + "|" + postcode).getBytes(StandardCharsets.UTF_8));
738	            StringBuilder hex = new StringBuilder(digest.length * 2);
739	            for (byte b : digest) {
740	                hex.append(String.format("%02x", b));
741	            }
742	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
743	        } catch (NoSuchAlgorithmException ex) {
744	            throw new IllegalStateException("SHA-256 not available", ex);
745	        }
746	    }
747	
748	    /**
749	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
750	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
751	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
752	     * string.
753	     */
754	    private String toHouseholdKey(String value) {
755	        if (value == null) {
756	            return "";
757	        }
758	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
759	    }
