761	    /**
762	     * Applies the owner's address, preferring the structured form over the flat one. The structured
763	     * {@code addressLine1}/{@code addressLine2} and the flat {@code address} are each normalized (see
764	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
765	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (a
766	     * blank {@code addressLine2} is stored as {@code null}), and the composed {@code address} is the
767	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
768	     * appended when an {@code addressLine2} is present. Otherwise the flat {@code address} is used for
769	     * backward compatibility: the normalized flat value becomes both {@code addressLine1} and the
770	     * stored {@code address}, with no {@code addressLine2}. Everything that later reads the owner's
771	     * address therefore sees the structured value when present, falling back to the flat one.
772	     *
773	     * @param owner the owner being created
774	     * @param dto   the submitted owner fields
775	     */
776	    private void applyAddress(Owner owner, OwnerFieldsDto dto) {
777	        String line1 = normalizeAddress(dto.getAddressLine1());
778	        String line2 = normalizeAddress(dto.getAddressLine2());
779	        String flat = normalizeAddress(dto.getAddress());
780	        String effectiveLine1 = line1.isEmpty() ? flat : line1;
781	        String effectiveLine2 = line1.isEmpty() ? "" : line2;
782	        String composed = effectiveLine2.isEmpty()
783	            ? effectiveLine1
784	            : effectiveLine1 + " " + effectiveLine2;
785	        owner.setAddressLine1(effectiveLine1.isEmpty() ? null : effectiveLine1);
786	        owner.setAddressLine2(effectiveLine2.isEmpty() ? null : effectiveLine2);
787	        owner.setAddress(composed);
788	    }
