790	    /**
791	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
792	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
793	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
794	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
795	     * value, or one that is blank once trimmed, normalizes to an empty string.
796	     *
797	     * @param address the raw address value as submitted, may be {@code null}
798	     * @return the normalized address, or an empty string when none was supplied
799	     */
800	    private String normalizeAddress(String address) {
801	        if (address == null) {
802	            return "";
803	        }
804	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
805	        if (collapsed.isEmpty()) {
806	            return "";
807	        }
808	        String[] tokens = collapsed.split(" ");
809	        StringBuilder normalized = new StringBuilder(collapsed.length());
810	        for (int i = 0; i < tokens.length; i++) {
811	            if (i > 0) {
812	                normalized.append(' ');
813	            }
814	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
815	        }
816	        return normalized.toString();
817	    }
