51	
52	    /**
53	     * The month the fiscal year starts on (1 July).
54	     */
55	    private static final int FISCAL_YEAR_START_MONTH = 7;
56	
57	    /**
58	     * Derives the fiscal year (as an integer) of the given date. The fiscal year starts on 1 July,
59	     * so a date on or after 1 July belongs to the following calendar year's fiscal year (e.g.
60	     * 2026-07-01 is fiscal year 2027) while an earlier date takes the calendar year unchanged.
61	     */
62	    private int fiscalYearOf(LocalDate date) {
63	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
64	    }
65	
66	    /**
67	     * Derives the owner's {@code fiscalYear}, formatted {@code FY<YY>} where YY is the last two
68	     * digits of the fiscal year (starting 1 July) of the owner's business-day-adjusted
69	     * {@code registrationDate}. Returns {@code null} when no registration date is present.
70	     */
71	    protected String fiscalYear(Owner owner) {
72	        LocalDate registrationDate = owner.getRegistrationDate();
73	        if (registrationDate == null) {
74	            return null;
75	        }
76	        return String.format("FY%02d", fiscalYearOf(registrationDate) % 100);
77	    }
78	
79	    /**
80	     * Derives the owner's {@code ageBand} from their {@code birthDate} relative to their
81	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
82	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date was supplied, or when
83	     * the registration date (against which the age is measured) is absent.
84	     */
85	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
86	        LocalDate birthDate = owner.getBirthDate();
87	        LocalDate registrationDate = owner.getRegistrationDate();
88	        if (birthDate == null || registrationDate == null) {
89	            return null;
90	        }
91	        int age = Period.between(birthDate, registrationDate).getYears();
92	        if (age < 18) {
93	            return OwnerDto.AgeBandEnum.MINOR;
94	        }
95	        if (age < 65) {
96	            return OwnerDto.AgeBandEnum.ADULT;
97	        }
98	        return OwnerDto.AgeBandEnum.SENIOR;
99	    }
100	
101	    /**
102	     * The country calling codes (without the leading {@code '+'}) the display formatter recognises,
103	     * longest first so the correct code is matched before a shorter prefix of it. Australia
104	     * ({@code +61}) and the North American Numbering Plan ({@code +1}) mirror the codes the create
105	     * endpoint normalizes against.
106	     */
107	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
108	
109	    /**
110	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
111	     * humans as the country code, a space, then the national digits grouped in threes (e.g.
112	     * {@code +61412345678} becomes {@code +61 412 345 678}). Returns the raw value unchanged when it
113	     * is {@code null} or not an E.164 number ({@code '+'} followed by digits).
114	     */
115	    protected String telephoneDisplay(Owner owner) {
116	        String telephone = owner.getTelephone();
117	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
118	            return telephone;
119	        }
120	        String digits = telephone.substring(1);
121	        String countryCode = KNOWN_COUNTRY_CODES.stream()
122	            .filter(digits::startsWith)
123	            .findFirst()
124	            .orElse("");
125	        String national = digits.substring(countryCode.length());
126	        StringBuilder grouped = new StringBuilder();
127	        for (int i = 0; i < national.length(); i++) {
128	            if (i > 0 && i % 3 == 0) {
129	                grouped.append(' ');
130	            }
131	            grouped.append(national.charAt(i));
132	        }
133	        return "+" + countryCode + " " + grouped;
134	    }
135	
136	    /**
137	     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key:
138	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A {@code null}
139	     * email or householdId contributes an empty segment.
140	     */
141	    protected String identityKey(Owner owner) {
142	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
143	        String email = owner.getEmail() == null ? "" : owner.getEmail();
144	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
145	        return telephone + "|" + email + "|" + householdId;
146	    }
147	
148	    /**
149	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
150	     * present, otherwise {@code PHONE}.
151	     */
152	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
153	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
154	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
155	    }
156	
157	    /**
158	     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
159	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
160	     */
161	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
162	        "NSW", new int[] {2000, 2099},
163	        "VIC", new int[] {3000, 3099},
164	        "QLD", new int[] {4000, 4099});
165	
166	    /**
167	     * Derives the owner's locality (region) from the region-and-hash identity: it is the REGION
168	     * component of the owner's {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality now
169	     * moves in lockstep with the identity assigned on create. When no customer code has been
170	     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
171	     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
172	     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
173	     * Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither identifies a region.
174	     */
175	    protected String locality(Owner owner) {
176	        String customerCode = owner.getCustomerCode();
177	        if (customerCode != null) {
178	            int dash = customerCode.indexOf('-');
179	            if (dash > 0) {
180	                return customerCode.substring(0, dash);
181	            }
182	        }
183	        String fromPostcode = regionFromPostcode(owner.getPostcode());
184	        if (fromPostcode != null) {
185	            return fromPostcode;
186	        }
187	        String city = owner.getCity();
188	        if (city == null) {
189	            return "UNKNOWN";
190	        }
191	        return switch (city) {
192	            case "Sydney" -> "NSW";
193	            case "Melbourne" -> "VIC";
194	            case "Brisbane" -> "QLD";
195	            default -> "UNKNOWN";
196	        };
197	    }
198	
199	    /**
200	     * The IANA timezone of each region, keyed by region code (NSW->Australia/Sydney,
201	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane).
202	     */
203	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
204	        "NSW", "Australia/Sydney",
205	        "VIC", "Australia/Melbourne",
206	        "QLD", "Australia/Brisbane");
207	
208	    /**
209	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's
210	     * {@link #locality(Owner) locality/region}, looked up in the fixed region-to-timezone table
211	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
212	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}).
213	     */
214	    protected String timezone(Owner owner) {
215	        return REGION_TIMEZONE.get(locality(owner));
216	    }
217	
218	    /**
219	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when
220	     * the postcode is absent, not 4 digits, or in no known range.
221	     */
222	    private String regionFromPostcode(String postcode) {
223	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
224	            return null;
225	        }
226	        int value = Integer.parseInt(postcode);
227	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
228	            int[] range = entry.getValue();
229	            if (value >= range[0] && value <= range[1]) {
230	                return entry.getKey();
231	            }
232	        }
233	        return null;
234	    }
235	
236	    /**
237	     * The minimum household size (counting the owner itself) that earns household membership
238	     * points.
239	     */
240	    private static final int HOUSEHOLD_POINTS_SIZE = 3;
241	
